      btn.setAttribute('aria-pressed', document.body.classList.contains('slow-mode'));
    });

    // ===== MODO SUAVE (CONTENIDO) =====
    document.getElementById('toggleContent').addEventListener('click', () => {
      const chunks = document.querySelectorAll('.content-chunk');
      const isSoft = document.body.classList.toggle('soft-mode');
      chunks.forEach(chunk => {
        chunk.style.opacity = isSoft ? '0.7' : '1';
        chunk.style.filter = isSoft ? 'blur(0.3px)' : 'none';
      });
      const btn = document.getElementById('toggleContent');
      btn.textContent = isSoft ? '✅ Modo Suave' : '⚠️ Modo Suave';
      btn.setAttribute('aria-pressed', isSoft);
    });

    // ===== TEST RÁPIDO =====
    document.getElementById('quickTest').addEventListener('submit', e => {
      e.preventDefault();
      const checks = document.querySelectorAll('#quickTest input[type="checkbox"]:checked');
      const score = checks.length;
      const res = document.getElementById('testResult');

      res.style.display = 'block';
      res.style.background = score >= 4 ? '#ffebee' : score >= 2 ? '#fff3cd' : '#e8f5e9';
      res.style.borderLeft = `5px solid ${score >= 4 ? '#c9503e' : score >= 2 ? '#ffc107' : '#2a7d4f'}`;

