          <br>✅ Aquí tienes <a href="#recursos">recursos verificados</a>.`;
      } else if (score >= 2) {
        res.innerHTML = `<strong>Señales presentes.</strong><br>
          Tu cuerpo ya está respondiendo. No estás roto/a; está en modo supervivencia. 
          <br><br>
          ✅ Activa el <a href="#sanacion">Paso 1 de Sanación</a>. 
          <br>✅ Revisa el <a href="#diccionario">Diccionario</a> para identificar señales tempranas.`;
      } else {
        res.innerHTML = `<strong>Vigilancia saludable.</strong><br>
          Mantén tus anclajes externos y revisa el <a href="#diccionario">Diccionario</a> para identificar señales tempranas. 
          <br><br>
          💡 Recordatorio: La manipulación suele comenzar de forma sutil. Confía en tu intuición.`;
      }
      res.focus();
    });

    // ===== CHAT SEGURO (ÁRBOL DE DECISIÓN LOCAL) =====
    document.getElementById('sendChat').addEventListener('click', () => {
      const input = document.getElementById('chatInput');
      const txt = input.value.trim().toLowerCase();
      const res = document.getElementById('chatResponse');

      if (!txt) {
        res.textContent = "Escribe algo para comenzar. Estoy aquí para escucharte.";
        return;
      }

      // Detección de crisis (prioridad máxima)
      if (/(miedo|peligro|suicidio|herir|morir|lastimar|acabar)/i.test(txt)) {
        res.innerHTML = `⚠️ <strong>Si hay riesgo inmediato, llama al 112 o 016 ahora.</strong><br>
          Tu seguridad física es prioritaria. Esta conversación puede esperar.<br>
          <button class="btn btn-warning" onclick="window.location='tel:112'" style="margin-top:0.5rem;">📞 LLAMAR 112 AHORA</button>`;
        input.value = '';
        return;
      }

      // Respuestas validadas según intención
      let reply = "Es normal sentir esto. Lo que viviste no es tu culpa. ¿Quieres practicar una respuesta o solo soltar?";

      if (/(límite|decirle|poner|frase|responder)/i.test(txt)) {
        reply = "Opción A: 'No acepto que me hables así.' <br>Opción B: 'Si continúas, termino esta conversación.' <br>¿Cuál resuena más con tu cuerpo AHORA?";
      }
      if (/(culpa|malo|malvado|egoísta)/i.test(txt)) {
        reply = "Es normal sentir culpa cuando rompes patrones antiguos. Tu cerebro aprendió que 'ser bueno/a' = seguridad. Ahora estás reentrenando: 'ser auténtico/a' = seguridad. ¿Quieres practicar una frase o solo soltar?";
      }
      if (/(cansado|agotado|fatiga|niebla)/i.test(txt)) {
        reply = "Tu cuerpo está respondiendo a estrés prolongado. Prueba: 1) Bebe agua. 2) Respira 4-7-8 tres veces. 3) Mira por la ventana 1 minuto. ¿Quieres que te guíe en la respiración?";
      }
      if (/(solo|aislado|nadie)/i.test(txt)) {
        reply = "No estás solo/a/e. Esta plataforma es tu espacio seguro. ¿Quieres ver recursos de apoyo comunitario o practicar una conversación?";
      }

      res.innerHTML = reply;
      input.value = '';
      res.focus();
    });

    // Permitir Enter para enviar en chat
    document.getElementById('chatInput').addEventListener('keypress', e => {
      if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        document.getElementById('sendChat').click();
      }
    });

    // ===== ACCESIBILIDAD: FOCO INICIAL =====
    window.addEventListener('load', () => {
      // Enfocar primer elemento interactivo para navegación por teclado
      const firstInteractive = document.querySelector('a[href], button, input');
      if (firstInteractive) firstInteractive.focus();
    });
  </script>
