  <script>
    // Controles de accesibilidad y carga cognitiva
    document.getElementById('btnSlow').addEventListener('click', () => {
      document.body.classList.toggle('slow');
      const b = document.getElementById('btnSlow');
      b.textContent = document.body.classList.contains('slow') ? '✅ Lectura lenta' : '🐌 Lectura lenta';
      b.setAttribute('aria-pressed', document.body.classList.contains('slow'));
    });
    document.getElementById('btnSoft').addEventListener('click', () => {
      const chunks = document.querySelectorAll('.chunk');
      const isSoft = document.body.classList.toggle('soft');
      chunks.forEach(c => { c.style.opacity = isSoft ? '0.7' : '1'; });
      const b = document.getElementById('btnSoft');
      b.textContent = isSoft ? '✅ Modo suave' : '⚠️ Modo suave';
      b.setAttribute('aria-pressed', isSoft);
    });

    // Test de autoconocimiento
    document.getElementById('formTest').addEventListener('submit', e => {
      e.preventDefault();
      const score = document.querySelectorAll('#formTest input:checked').length;
      const res = document.getElementById('resTest');
      res.style.display = 'block';
      res.style.background = score >= 4 ? '#fee2e2' : score >= 2 ? '#fef3c7' : '#dcfce7';
      res.style.borderLeft = `5px solid ${score >= 4 ? '#dc2626' : score >= 2 ? '#d97706' : '#059669'}`;
      res.innerHTML = score >= 4 
        ? `<strong>Señales altas.</strong> Tu cuerpo responde a sobrecarga sostenida. Activa la <a href="#recuperacion">Fase 1</a>. Considera 016 o profesional afirmativo.`
        : score >= 2 
        ? `<strong>Señales presentes.</strong> Tu sistema nervioso está en alerta. Activa la <a href="#recuperacion">Fase 1</a>. Revisa el diccionario.`
        : `<strong>Vigilancia saludable.</strong> Mantén anclajes externos. Revisa el diccionario para señales tempranas.`;
      res.focus();
    });

    // Chat seguro (árbol de decisión local, polivagal + TF-CBT)
    document.getElementById('btnChat').addEventListener('click', () => {
      const input = document.getElementById('inputChat');
      const txt = input.value.trim().toLowerCase();
      const res = document.getElementById('resChat');
      if (!txt) { res.textContent = "Escribe algo para comenzar. Estoy aquí."; return; }

      if (/(miedo|peligro|suicidio|herir|morir|lastimar|acabar)/i.test(txt)) {
        res.innerHTML = `⚠️ <strong>Si hay riesgo inmediato, llama al 112 o 016 ahora.</strong><br>Tu seguridad física es prioritaria.<br><button class="btn btn-warn" onclick="window.location='tel:112'" style="margin-top:0.4rem;">📞 LLAMAR 112</button>`;
        input.value = ''; return;
      }

      let reply = "Es normal sentir esto. Lo que viviste no es tu culpa. ¿Quieres practicar una respuesta o solo soltar?";
      if (/(límite|decirle|poner|frase|responder)/i.test(txt)) 
        reply = "Opción A: 'No acepto que me hables así.'<br>Opción B: 'Si continúas, termino esta conversación.'<br>¿Cuál resuena más con tu cuerpo AHORA?";
      if (/(culpa|malo|malvado|egoísta)/i.test(txt)) 
        reply = "Es normal sentir culpa cuando rompes patrones antiguos. Tu cerebro aprendió que 'ser bueno/a' = seguridad. Ahora estás reentrenando: 'ser auténtico/a' = seguridad.";
      if (/(cansado|agotado|fatiga|niebla)/i.test(txt)) 
        reply = "Tu cuerpo responde a estrés prolongado. Prueba: 1) Bebe agua. 2) Respira 4-7-8 tres veces. 3) Mira por la ventana 1 min.";
      if (/(solo|aislado|nadie)/i.test(txt)) 
        reply = "No estás solo/a/e. Esta plataforma es tu espacio seguro. ¿Quieres ver recursos de apoyo o practicar una conversación?";

      res.innerHTML = reply; input.value = ''; res.focus();
    });
    document.getElementById('inputChat').addEventListener('keypress', e => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); document.getElementById('btnChat').click(); }
    });
  </script>
</body>
</html>
