      if (/(miedo|peligro|suicidio|herir|morir|lastimar|acabar)/i.test(txt)) {
        res.innerHTML = `⚠️ <strong>Si hay riesgo inmediato, llama al 112 o 016 ahora.</strong><br>Tu seguridad física es prioritaria.<br><button class="btn btn-warn" onclick="window.location='tel:112'" style="margin-top:0.4rem;">📞 LLAMAR 112</button>`;
        input.value = ''; return;
      }

      let reply = "Es normal sentir esto. Lo que viviste no es tu culpa. ¿Quieres practicar una respuesta o solo soltar?";
      if (/(límite|decirle|poner|frase|responder)/i.test(txt)) 
        reply = "Opción A: 'No acepto que me hables así.'<br>Opción B: 'Si continúas, termino esta conversación.'<br>¿Cuál resuena más con tu cuerpo AHORA?";
      if (/(culpa|malo|malvado|egoísta)/i.test(txt)) 
        reply = "Es normal sentir culpa cuando rompes patrones antiguos. Tu cerebro aprendió que 'ser bueno/a' = seguridad. Ahora estás reentrenando: 'ser auténtico/a' = seguridad.";
      if (/(cansado|agotado|fatiga|niebla)/i.test(txt)) 
        reply = "Tu cuerpo responde a estrés prolongado. Prueba: 1) Bebe agua. 2) Respira 4-7-8 tres veces. 3) Mira por la ventana 1 min.";
      if (/(solo|aislado|nadie)/i.test(txt)) 
        reply = "No estás solo/a/e. Esta plataforma es tu espacio seguro. ¿Quieres ver recursos de apoyo o practicar una conversación?";

      res.innerHTML = reply; input.value = ''; res.focus();
    });
    document.getElementById('inputChat').addEventListener('keypress', e => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); document.getElementById('btnChat').click(); }
    });
